#!/usr/bin/env bash
# Группа CI «fast-1» — половина набора `not slow` (маркер slow не включён).
# v3.30: группы не перечисляют команды по одной; всё живёт в pytest, разбиение — по маркерам и
# именам, чтобы джобы шли параллельно и примерно равно по времени.
set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1   # байткод в дереве ломает проверку целостности managed
cd "$(dirname "$0")/../.."
# АРХИТЕКТУРНЫЙ ШАГ (2026-09-08, #465). После #625 шард `fast` держался у самой стены 180 c и не
# был надёжно под ней: тот же состав давал на раннере и 169 c, и 209 c (разброс ±40 c). Остаток —
# ОБЪЁМ (тысячи тестов < 10 c / 4 ядра), честно снять его маркером `slow` уже нельзя (кандидаты
# ~4–5 c/тест, ниже порога >10 c). Единственный надёжный зазор — больше параллелизма: `fast` разбит
# на два ШАРДА `fast-1`/`fast-2`, каждый гонит примерно половину набора на своих 4 ядрах и уходит
# под ~110–140 c с запасом на разброс раннера.
#
# ПАРТИЦИЯ ПО СЧЁТУ = ПАРТИЦИЯ ПО ВРЕМЕНИ. Набор `fast` после #625 volume-bound (полюсов нет,
# тесты равномерны < 10 c), поэтому равный ЧИСЛОМ раскол даёт равное ВРЕМЯ. Замер `--collect-only`
# на 2026-09-08: fast-1 = 2757, fast-2 = 2848, сумма 5605 = весь набор `not slow`. Половины близки.
#
# Как работает маршрутизация (иначе «граница по первой букве» обманчива): `-k` матчит ПОДСТРОКУ по
# имени функции/класса И по имени файла-модуля. Файл с именем модуля из набора (например
# `test_backlog_*`, `test_release_*`, `test_specify_*`, `test_ci_*`) едет СЮДА целиком; в остальных
# файлах СЮДА подтягиваются поштучно функции `test_r…/test_s…/test_c…/test_b…`, а прочие — в fast-2.
# То есть многие файлы РАСПАДАЮТСЯ между шардами по имени функции — это и есть исходная схема
# selftests-a/-m «по первой букве». Партиция полная и непересекающаяся по построению: fast-2 — ровно
# `not (то, что здесь)`, ни один тест не потерян и не гоняется дважды. Баланс уточнять по фактическим
# временам джоб CI, а не по буквам. Имена CI-контекстов новые (`quality (fast-1, …)`) — required-
# статусы branch protection обязан обновить владелец (см. описание PR), иначе старый `fast` не
# отчитается и заблокирует ветку.
python3 -m pytest -n auto --dist loadfile tests/ -q -m "not slow" \
  -k "test_r or test_s or test_c or test_b"
